ETAPA_DO_EQUIPAMENTO = {
    "FELLER": "CORTE_FELLER",
    "HARVESTER": "CORTE_FELLER",
    "SKIDDER": "ARRASTE",
    "GARRA_TRACADORA": "TRACAMENTO",
    "MOTOSSERRA": "CORTE_MOTOSSERRA",
    "BALDEIO_MANUAL": "EMBANDEIRAMENTO",
}


def etapa_pelos_equipamentos(apps, schema_editor):
    Colheita = apps.get_model("sistema", "Colheita")
    for colheita in Colheita.objects.all():
        equipamentos = colheita.equipamentos or []
        etapa = next(
            (ETAPA_DO_EQUIPAMENTO[e] for e in equipamentos if e in ETAPA_DO_EQUIPAMENTO),
            "CORTE_MOTOSSERRA" if colheita.sistema == "MANUAL" else "CORTE_FELLER",
        )
        colheita.etapa = etapa
        colheita.tipo_execucao = "TERCEIRIZADA" if colheita.fornecedor_id else "PROPRIA"
        colheita.save(update_fields=["etapa", "tipo_execucao"])


def novos_padroes_de_casas(apps, schema_editor):
    Parametros = apps.get_model("sistema", "Parametros")
    Parametros.objects.filter(casas_decimais_ha=4).update(casas_decimais_ha=2)
    Parametros.objects.filter(casas_decimais_mdc=3).update(casas_decimais_mdc=2)


